using System.ComponentModel;
using ModelContextProtocol.Server;

[McpServerToolType]
public static class ConfigTools
{
    [McpServerTool, Description("Looks up a configuration value by key.")]
    public static string GetConfigValue(
        [Description("The configuration key to look up")] string key)
    {
        var defaults = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase)
        {
            ["environment"] = "production",
            ["region"] = "us-east-1",
            ["log_level"] = "Information",
            ["max_retries"] = "3"
        };

        return defaults.TryGetValue(key, out var value)
            ? value
            : $"Unknown key: {key}";
    }
}

using System.ComponentModel;
using System.Text.Json;
using ModelContextProtocol.Server;

[McpServerResourceType]
public static class ConfigResources
{
    [McpServerResource(
        UriTemplate = "config://app",
        Name = "App Configuration",
        MimeType = "application/json"),
     Description("Returns the full application configuration as JSON.")]
    public static string GetAppConfig()
    {
        var config = new
        {
            Environment = "production",
            Region = "us-east-1",
            LogLevel = "Information",
            MaxRetries = 3,
            Features = new
            {
                CacheEnabled = true,
                RateLimiting = true,
                MaxRequestsPerMinute = 60
            }
        };

        return JsonSerializer.Serialize(config, new JsonSerializerOptions { WriteIndented = true });
    }

    [McpServerResource(
        UriTemplate = "config://features/{featureName}",
        Name = "Feature Flag",
        MimeType = "application/json"),
     Description("Returns the status of a specific feature flag.")]
    public static string GetFeatureFlag(string featureName)
    {
        var features = new Dictionary<string, bool>(StringComparer.OrdinalIgnoreCase)
        {
            ["cache"] = true,
            ["rate_limiting"] = true,
            ["dark_mode"] = false,
            ["beta_api"] = false
        };

        var enabled = features.TryGetValue(featureName, out var value) && value;

        return JsonSerializer.Serialize(new { Feature = featureName, Enabled = enabled });
    }
}

